contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint m, uint d) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (d)); require(d <= 1000000000000000000000000000000);
        c.SetMinSum(m); if (__ESBMC_reverted()) return;
        c.Deposit{value: d}(); if (__ESBMC_reverted()) return;
        uint recordedBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint ethBefore = address(c).balance;
        bool reverted;
        c.Collect(0); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint recordedAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint ethAfter = address(c).balance;
        assert(!reverted && recordedAfter == recordedBefore && ethAfter == ethBefore);
    }
    receive() external payable {}
}

