pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 m, uint256 d) internal {
        d = bound(d, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        try c.SetMinSum(m) {} catch { return; }
        try c.Deposit{value: d}() {} catch { return; }
        uint256 recordedBefore;
        try c.balances(address(this)) returns (uint256 __r) { recordedBefore = __r; } catch { return; }
        uint ethBefore = address(c).balance;
        bool reverted;
        try c.Collect(0) { reverted = false; } catch { reverted = true; }
        uint256 recordedAfter;
        try c.balances(address(this)) returns (uint256 __r) { recordedAfter = __r; } catch { return; }
        uint ethAfter = address(c).balance;
        assertTrue(!reverted && recordedAfter == recordedBefore && ethAfter == ethBefore);
    }

    function testFuzz_run(uint256 m, uint256 d) public {
        _run(m, d);
    }

    receive() external payable {}
}
